# DeepSeek Harness tray autostart launcher (generated by the dsh-autostart plugin).
#
# Started at sign-in by the Startup-folder shortcut through dsh-tray-start.vbs:
#   wscript.exe (Microsoft-signed) -> hidden powershell.exe (Microsoft-signed) -> this script.
# The script starts DeepSeek Harness and hides its primary window so the app
# lands in the system tray instead of popping up on the desktop.
#
# This file is written by the dsh-autostart plugin; edit the plugin payload, not
# this generated copy. The __DSH_EXE_PATH__ placeholder is replaced at deploy time.

param(
    [string]$ExePath = '__DSH_EXE_PATH__',
    [string]$WindowClass = 'Chrome_WidgetWin_1',
    [int]$TimeoutSeconds = 120,
    [int]$GraceSeconds = 4,
    [string]$LogPath = ''
)

$ErrorActionPreference = 'Stop'

if (-not $LogPath -or $LogPath.Trim().Length -eq 0) {
    $LogPath = Join-Path $env:LOCALAPPDATA 'DSH\tray-start.log'
}

$logDirectory = Split-Path -Parent $LogPath
if ($logDirectory -and -not (Test-Path -LiteralPath $logDirectory)) {
    New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
}

function Write-TrayLog([string]$Message) {
    $line = '{0} {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Message
    try {
        Add-Content -LiteralPath $LogPath -Value $line -Encoding UTF8
    } catch {
        # logging must never prevent the app from starting
    }
}

$appName = [System.IO.Path]::GetFileNameWithoutExtension($ExePath)
Write-TrayLog ('start: exe={0} class={1}' -f $ExePath, $WindowClass)

$running = @(Get-Process -Name $appName -ErrorAction SilentlyContinue)
if ($running.Count -gt 0) {
    Write-TrayLog 'app already running; nothing to do'
    exit 0
}

# Hides every visible window of the launched process whose class matches
# $WindowClass. Runs a few milliseconds at a time and gives the app a grace
# window, because the primary window can appear slightly after the process.
$hideSource = @'
using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

namespace DshTrayHide
{
    internal static class Native
    {
        internal delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

        [DllImport("user32.dll")]
        internal static extern bool EnumWindows(EnumWindowsProc callback, IntPtr lParam);

        [DllImport("user32.dll")]
        internal static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint processId);

        [DllImport("user32.dll")]
        internal static extern bool IsWindowVisible(IntPtr hWnd);

        [DllImport("user32.dll", CharSet = CharSet.Unicode)]
        internal static extern int GetClassName(IntPtr hWnd, StringBuilder name, int maxCount);

        [DllImport("user32.dll")]
        internal static extern bool ShowWindow(IntPtr hWnd, int command);

        internal const int SwHide = 0;
    }

    public static class WindowHider
    {
        public static int HideWindowsForProcess(int processId, string requiredClassName, int timeoutMs, int graceMs)
        {
            Stopwatch watch = Stopwatch.StartNew();
            bool hidAny = false;
            DateTime lastHide = DateTime.MinValue;

            while (watch.ElapsedMilliseconds < timeoutMs)
            {
                bool hidThisPass = false;

                Native.EnumWindows((hWnd, lParam) =>
                {
                    uint pid;
                    Native.GetWindowThreadProcessId(hWnd, out pid);
                    if (pid != (uint)processId || !Native.IsWindowVisible(hWnd))
                    {
                        return true;
                    }

                    StringBuilder name = new StringBuilder(256);
                    Native.GetClassName(hWnd, name, name.Capacity);
                    string className = name.ToString();
                    if (requiredClassName.Length > 0 && !string.Equals(className, requiredClassName, StringComparison.Ordinal))
                    {
                        return true;
                    }

                    Native.ShowWindow(hWnd, Native.SwHide);
                    hidThisPass = true;
                    return true;
                }, IntPtr.Zero);

                if (hidThisPass)
                {
                    hidAny = true;
                    lastHide = DateTime.UtcNow;
                }

                if (hidAny && (DateTime.UtcNow - lastHide).TotalMilliseconds >= graceMs)
                {
                    return 1;
                }

                Thread.Sleep(5);
            }

            return hidAny ? 2 : 0;
        }
    }
}
'@

$hideType = $null
try {
    Add-Type -TypeDefinition $hideSource -Language CSharp -ErrorAction Stop
    $hideType = [DshTrayHide.WindowHider]
} catch {
    Write-TrayLog ('Add-Type failed: {0}; the app will start without hiding its window' -f $_.Exception.Message)
}

$process = Start-Process -FilePath $ExePath -PassThru
Write-TrayLog ('launched pid={0}' -f $process.Id)

if ($null -ne $hideType) {
    $hideResult = $hideType::HideWindowsForProcess($process.Id, $WindowClass, $TimeoutSeconds * 1000, $GraceSeconds * 1000)
    switch ($hideResult) {
        1 { Write-TrayLog ('window hidden (pid={0})' -f $process.Id) }
        2 { Write-TrayLog ('window hidden then stayed hidden; grace ended (pid={0})' -f $process.Id) }
        default { Write-TrayLog ('no window seen within {0}s (pid={1})' -f $TimeoutSeconds, $process.Id) }
    }
}

exit 0
